package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        String cs1 = "test";
        // Covers: if (cs1 == cs2) return true;
        assertTrue(StringUtils.equals(cs1, cs1));
    }

    @Test
    public void testEquals_BothNull() {
        // Covers: if (cs1 == cs2) return true; (null == null)
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_FirstNull() {
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals(null, "test"));
    }

    @Test
    public void testEquals_SecondNull() {
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals("test", null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        // Covers: if (cs1 instanceof String && cs2 instanceof String) return cs1.equals(cs2);
        assertTrue(StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        // Covers: if (cs1 instanceof String && cs2 instanceof String) return cs1.equals(cs2);
        assertFalse(StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_OneStringOneStringBuilder_Equal() {
        // Covers: falls through to CharSequenceUtils.regionMatches logic
        // cs1 is String, cs2 is StringBuilder (not both Strings)
        StringBuilder sb = new StringBuilder("abc");
        assertTrue(StringUtils.equals("abc", sb));
    }

    @Test
    public void testEquals_BothStringBuilder_Equal() {
        // Covers: falls through to CharSequenceUtils.regionMatches logic
        StringBuilder sb1 = new StringBuilder("abc");
        StringBuilder sb2 = new StringBuilder("abc");
        assertTrue(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_FirstLongerThanSecond_Mismatch() {
        // Covers: cs1.length() >= cs2.length() && CharSequenceUtils.regionMatches(...)
        // Here cs1.length() >= cs2.length() is true, but regionMatches is false
        StringBuilder sb1 = new StringBuilder("abcd");
        StringBuilder sb2 = new StringBuilder("abc");
        // Note: The logic in the provided code is: cs1.length() >= cs2.length() && regionMatches(cs1, ..., cs2, ...)
        // If cs1="abcd" and cs2="abc", length check passes, but regionMatches(cs1, false, 0, cs2, 0, cs1.length()) 
        // will likely fail because cs2 length is less than cs1.length() requested in regionMatches call.
        assertFalse(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_FirstShorterThanSecond() {
        // Covers: cs1.length() >= cs2.length() returns false
        StringBuilder sb1 = new StringBuilder("abc");
        StringBuilder sb2 = new StringBuilder("abcd");
        assertFalse(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_CharSequenceMismatchType() {
        // Covers: cs1 is not String, cs2 is String
        StringBuilder sb1 = new StringBuilder("abc");
        String s2 = "abc";
        assertTrue(StringUtils.equals(sb1, s2));
    }
}
